SELECT COALESCE(SUM(i.quantity), 0) FROM xsy_order_return_receipt_item i
JOIN xsy_order_return_item ri ON ri.id = i.return_item_id
WHERE ri.order_item_id = #{orderItemId}

SELECT COALESCE(SUM(COALESCE(stock_quantity, quantity)), 0)
FROM xsy_order_return_receipt_item
WHERE source_sales_out_movement_id = #{sourceSalesOutMovementId}
